type Category={focusDe:string;focusEn:string;rolesDe:string;rolesEn:string;contextDe:string;contextEn:string};
const categories:Record<string,Category>={
  agency:{focusDe:"Beratung;Konzeption;Umsetzung;Analyse",focusEn:"Consulting;Concept development;Implementation;Analytics",rolesDe:"Marketing;Kommunikation;Digitalteam;Vertrieb;Geschäftsführung;Einkauf",rolesEn:"Marketing;Communications;Digital team;Sales;Executive management;Procurement",contextDe:"Bei der Beauftragung zählen Zielgruppe, Leistungen, Datenzugang und Eigentum an Ergebnissen. Strategie, Produktion und laufende Betreuung sollten separat beschrieben werden; Referenzen ersetzen keine projektspezifische Prüfung.",contextEn:"Selection depends on audience, scope, data access and ownership of deliverables. Strategy, production and ongoing support should be specified separately; references do not replace project-specific review."},
  tech:{focusDe:"Software;Integration;Daten;Betrieb",focusEn:"Software;Integration;Data;Operations",rolesDe:"CIO;IT-Architektur;IT-Betrieb;Fachbereich;Datenschutz;Einkauf",rolesEn:"CIO;IT architecture;IT operations;Business functions;Privacy;Procurement",contextDe:"Für die Auswahl sind bestehende Systeme, Schnittstellen, Zugriffsrechte und Betriebskosten maßgeblich. Interessenten sollten Leistungsgrenzen, Implementierungsaufwand, Support und die Zuständigkeit für Daten und Sicherheit klären.",contextEn:"Selection depends on existing systems, interfaces, access rights and operating costs. Buyers should clarify product boundaries, implementation effort, support and responsibility for data and security."},
  ai:{focusDe:"KI-Anwendungen;Datenintegration;Automatisierung;Betrieb",focusEn:"AI applications;Data integration;Automation;Operations",rolesDe:"CIO;KI-Team;Fachbereich;Datenmanagement;Datenschutz;Einkauf",rolesEn:"CIO;AI team;Business functions;Data management;Privacy;Procurement",contextDe:"Ein belastbarer Einsatz verlangt geeignete Daten, menschliche Kontrolle und messbare Aufgaben. Vor Einführung sollten Modellgrenzen, Datenflüsse, Integrationen, Kosten und Zuständigkeit im Betrieb geprüft werden.",contextEn:"Reliable use requires suitable data, human oversight and measurable tasks. Before deployment, teams should assess model limits, data flows, integrations, costs and operational ownership."},
  security:{focusDe:"Sicherheitsstrategie;Risikobewertung;Schutzmaßnahmen;Betrieb",focusEn:"Security strategy;Risk assessment;Protection measures;Operations",rolesDe:"CISO;Security Operations;IT-Betrieb;Compliance;Datenschutz;Einkauf",rolesEn:"CISO;Security operations;IT operations;Compliance;Privacy;Procurement",contextDe:"Die konkrete Eignung hängt von Schutzbedarf, vorhandenen Kontrollen und Betriebsmodell ab. Unternehmen sollten Reichweite, Verantwortlichkeiten, Integration, Nachweise und Reaktionswege vor einem Einsatz prüfen.",contextEn:"Fit depends on protection needs, existing controls and the operating model. Organizations should review scope, responsibilities, integration, evidence and response paths before adoption."},
  hr:{focusDe:"Personalberatung;Recruiting;Entwicklung;Prozessbegleitung",focusEn:"HR consulting;Recruiting;Development;Process support",rolesDe:"HR-Leitung;Recruiting;Personalentwicklung;Fachbereich;Geschäftsführung;Einkauf",rolesEn:"HR leadership;Recruiting;Learning and development;Business functions;Executive management;Procurement",contextDe:"Entscheidend sind Zielgruppe, rechtlicher Rahmen, Datenschutz und die Rolle interner Personalteams. Methoden, Erfolgskriterien, Betreuung und laufende Kosten sollten für jeden Auftrag konkret vereinbart werden.",contextEn:"Audience, legal framework, privacy and the role of internal HR teams matter. Methods, success measures, support and ongoing costs should be agreed for each engagement."},
  peopletech:{focusDe:"Feedbackerfassung;Auswertung;Datenschutz;Maßnahmenplanung",focusEn:"Feedback collection;Analysis;Privacy;Action planning",rolesDe:"HR-Leitung;Organisationsentwicklung;Führungskräfte;Betriebsrat;Datenschutz;Geschäftsführung",rolesEn:"HR leadership;Organization development;Managers;Works council;Privacy;Executive management",contextDe:"Für den Einsatz zählen Vertraulichkeit, Beteiligung und ein transparenter Umgang mit Ergebnissen. Die Organisation sollte Auswertungsrechte, Folgemaßnahmen, Betriebsratsbeteiligung und die Grenzen automatisierter Deutung klären.",contextEn:"Deployment depends on confidentiality, participation and transparent handling of results. Organizations should clarify access to analysis, follow-up actions, employee representation and the limits of automated interpretation."},
  certification:{focusDe:"Kriterien;Prüfverfahren;Kennzeichnung;Nachkontrolle",focusEn:"Criteria;Assessment process;Labelling;Follow-up checks",rolesDe:"Qualitätsmanagement;Recht;Kommunikation;Produktverantwortung;Einkauf;Geschäftsführung",rolesEn:"Quality management;Legal;Communications;Product ownership;Procurement;Executive management",contextDe:"Ein Siegel gilt nur für seinen belegten Prüfgegenstand und Zeitraum. Interessenten sollten Kriterien, Verfahren, Unabhängigkeit, Gebühren, Nutzungsrechte und Möglichkeiten der Nachkontrolle vor Verwendung klären.",contextEn:"A label applies only to its evidenced scope and period. Prospects should clarify criteria, methods, independence, fees, usage rights and follow-up checks before using it."},
  consumer:{focusDe:"Produktentwicklung;Materialien;Vertrieb;Kundenservice",focusEn:"Product development;Materials;Sales;Customer service",rolesDe:"Produktmanagement;Qualitätsmanagement;Handel;Einkauf;Kundenservice;Geschäftsführung",rolesEn:"Product management;Quality management;Retail;Procurement;Customer service;Executive management",contextDe:"Material, Maße und Gebrauchshinweise sollten zum Alltag der Nutzenden passen. Vertriebspartner sollten Verfügbarkeit, Rückgabe, Sicherheit, Kennzeichnung und die Verantwortung für Produktangaben prüfen.",contextEn:"Material, dimensions and instructions should suit everyday use. Distribution partners should check availability, returns, safety, labelling and responsibility for product claims."},
  training:{focusDe:"Training;Lerninhalte;Praxisübungen;Transfer",focusEn:"Training;Learning content;Practical exercises;Transfer",rolesDe:"HR;Weiterbildung;Fachbereich;Teamleitung;Teilnehmende;Einkauf",rolesEn:"HR;Learning and development;Business functions;Team leaders;Learners;Procurement",contextDe:"Lernziele, Vorkenntnisse und spätere Anwendung bestimmen das passende Format. Auftraggeber sollten Trainerqualifikation, Materialien, Terminplanung, Lernerfolg und Grenzen der vermittelten Inhalte prüfen.",contextEn:"Learning goals, prior knowledge and later application shape the right format. Buyers should assess trainer qualifications, materials, scheduling, learning outcomes and the limits of the content taught."},
  industry:{focusDe:"Entwicklung;Fertigung;Qualität;Lieferung",focusEn:"Engineering;Manufacturing;Quality;Delivery",rolesDe:"Produktion;Engineering;Qualitätsmanagement;Instandhaltung;Logistik;Einkauf",rolesEn:"Manufacturing;Engineering;Quality management;Maintenance;Logistics;Procurement",contextDe:"Technische Anforderungen, Stückzahlen, Normen und Liefertermine müssen zum Einsatz passen. Einkäufer sollten Materialien, Prüfverfahren, Dokumentation, Anpassungen und die Verantwortung entlang der Lieferkette abstimmen.",contextEn:"Technical specifications, quantities, standards and lead times must fit the application. Buyers should align materials, testing, documentation, customization and supply-chain responsibilities."},
  association:{focusDe:"Mitgliedschaft;Fachinformation;Vernetzung;Interessenvertretung",focusEn:"Membership;Specialist information;Networking;Advocacy",rolesDe:"Geschäftsführung;Fachreferate;Mitgliederbetreuung;Kommunikation;Public Affairs;Partnerschaften",rolesEn:"Executive management;Specialist teams;Member relations;Communications;Public affairs;Partnerships",contextDe:"Informationsangebote und Branchenpositionen sind von individuellen Lieferverträgen zu unterscheiden. Mitglieder sollten Beteiligungsformen, Zugang zu Formaten, fachliche Zuständigkeit und Reichweite öffentlicher Aussagen klären.",contextEn:"Information and industry positions differ from individual supply contracts. Members should clarify participation, access to formats, specialist responsibility and the reach of public statements."},
  travel:{focusDe:"Unterkünfte;Buchung;Gästeservice;Vermarktung",focusEn:"Accommodation;Booking;Guest services;Marketing",rolesDe:"Travel Management;Operations;Kundenservice;Vertrieb;Marketing;Partnerschaften",rolesEn:"Travel management;Operations;Customer service;Sales;Marketing;Partnerships",contextDe:"Für Angebote zählen Standort, Verfügbarkeit, Bedingungen und der tatsächlich leistende Vertragspartner. Betreiber und Vertriebspartner sollten Buchungswege, Stornierung, Service, Daten und Gebühren transparent abgrenzen.",contextEn:"Location, availability, terms and the actual contracting party shape the offer. Operators and distribution partners should distinguish booking flows, cancellation, service, data and fees."},
  finance:{focusDe:"Finanzprozesse;Transaktionen;Daten;Compliance",focusEn:"Financial processes;Transactions;Data;Compliance",rolesDe:"Finanzen;Controlling;Treasury;Compliance;Recht;Einkauf",rolesEn:"Finance;Controlling;Treasury;Compliance;Legal;Procurement",contextDe:"Anwendbarkeit und Risiken hängen von Produkt, Rechtsraum und Vertrag ab. Interessenten sollten Gebühren, Sicherung, Gegenparteien, Datenzugriff und regulatorische Zuständigkeiten unabhängig prüfen.",contextEn:"Applicability and risks depend on product, jurisdiction and contract. Prospects should independently review fees, safeguards, counterparties, data access and regulatory responsibilities."},
  legal:{focusDe:"Rechtsberatung;Verträge;Regulierung;Umsetzung",focusEn:"Legal advice;Contracts;Regulation;Implementation",rolesDe:"Rechtsabteilung;Compliance;Datenschutz;Geschäftsführung;Fachbereich;Einkauf",rolesEn:"Legal team;Compliance;Privacy;Executive management;Business functions;Procurement",contextDe:"Der konkrete Beratungsauftrag richtet sich nach Sachverhalt, Rechtsraum und Mandat. Unternehmen sollten Zuständigkeiten, Konflikte, Fristen, Dokumentation und das Verhältnis zu technischen Dienstleistern vorab klären.",contextEn:"The advisory mandate depends on facts, jurisdiction and engagement terms. Organizations should clarify ownership, conflicts, deadlines, documentation and the relationship with technical providers."},
  media:{focusDe:"Inhalte;Publikation;Reichweite;Vermarktung",focusEn:"Content;Publishing;Audience reach;Marketing",rolesDe:"Redaktion;PR;Marketing;Mediaplanung;Vertrieb;Geschäftsführung",rolesEn:"Editorial;PR;Marketing;Media planning;Sales;Executive management",contextDe:"Publizistische Reichweite, bezahlte Platzierung und eigene Produktleistungen sind getrennt zu bewerten. Partner sollten Zielgruppe, Kennzeichnung, Nutzungsrechte, Messung und Verantwortlichkeit für Aussagen vereinbaren.",contextEn:"Editorial reach, paid placement and proprietary products need separate assessment. Partners should agree audience, disclosure, usage rights, measurement and responsibility for claims."},
  energy:{focusDe:"Energiedaten;Optimierung;Integration;Betrieb",focusEn:"Energy data;Optimization;Integration;Operations",rolesDe:"Energiemanagement;Technik;Gebäudebetrieb;Nachhaltigkeit;Controlling;Einkauf",rolesEn:"Energy management;Engineering;Facilities operations;Sustainability;Controlling;Procurement",contextDe:"Die Wirtschaftlichkeit hängt von Messpunkten, Lastprofilen und vorhandener Infrastruktur ab. Vor Einführung sollten Datenqualität, Schnittstellen, Verantwortung im Betrieb und nachprüfbare Einsparungen definiert werden.",contextEn:"Economics depend on measurement points, load profiles and existing infrastructure. Before deployment, teams should define data quality, interfaces, operational responsibility and verifiable savings."},
  service:{focusDe:"Beratung;Prozessgestaltung;Umsetzung;Betreuung",focusEn:"Consulting;Process design;Implementation;Support",rolesDe:"Geschäftsführung;Operations;Fachbereich;Projektleitung;Qualität;Einkauf",rolesEn:"Executive management;Operations;Business functions;Project management;Quality;Procurement",contextDe:"Leistungsumfang und Nutzen hängen vom konkreten Auftrag ab. Unternehmen sollten Ziele, Methoden, Verantwortliche, Übergaben, Ergebnisse und Kosten schriftlich eingrenzen und Referenzen im passenden Kontext prüfen.",contextEn:"Scope and value depend on the specific engagement. Organizations should define objectives, methods, owners, handovers, results and cost in writing, then assess references in context."},
};
